def route_surface_needs_depth_bias(shape_name, material_name=""):
    """Identify thin native route overlays that sit coplanar with grass."""
    names = (str(shape_name).casefold(), str(material_name).casefold())
    return any("mtrw" in name or "mtrouteopague" in name or "routeopague" in name
               for name in names)


