def build_document(scene: dict, *, embedded: bool = False) -> str:
    """Build an offline preview with escaped scene data and no remote scripts."""
    compact_scene = dict(scene)
    compact_scene["embedded"] = bool(embedded)
    compact_shapes = []
    for original in scene.get("shapes", ()):
        shape = dict(original)
        if "vertexColors" in shape:
            positions = shape.get("positions")
            colors = shape["vertexColors"]
            if not isinstance(positions, (list, tuple)) or not isinstance(colors, (list, tuple)) or len(colors) != len(positions):
                raise ValueError("_c0 vertex colors must match the position count")
            for index, color in enumerate(colors):
                if not isinstance(color, (list, tuple)) or len(color) != 4:
                    raise ValueError(f"_c0 vertex color {index} must contain four channels")
                if not all(math.isfinite(float(value)) and abs(float(value)) <= 65504 for value in color):
                    raise ValueError(f"_c0 vertex color {index} contains an invalid channel")
        for field, typecode in (("positions", "f"), ("normals", "f"), ("uvs", "f"), ("vertexColors", "f"), ("indices", "H")):
            if field not in shape:
                continue
            values = array(typecode)
            for item in shape[field]:
                if isinstance(item, (list, tuple)):
                    values.extend(item)
                else:
                    values.append(item)
            if values.itemsize != (4 if typecode == "f" else 2):
                raise ValueError(f"Platform array size is unsupported for {field}")
            if sys.byteorder != "little":
                values.byteswap()
            shape[f"{field}Packed"] = base64.b64encode(values.tobytes()).decode("ascii")
            if field == "indices":
                shape["indexCount"] = len(shape[field])
            del shape[field]
        uv_attributes = shape.pop("uvAttributes", None)
        if uv_attributes is not None:
            if not isinstance(uv_attributes, dict):
                raise ValueError("UV attributes must be a name-to-coordinates mapping")
            packed_uv_attributes = {}
            for name, coordinates in uv_attributes.items():
                if (not isinstance(name, str) or not name.startswith("_u") or
                        not name[2:].isdecimal()):
                    raise ValueError("Unsupported UV attribute name")
                if name == "_u0" and "uvsPacked" in shape:
                    continue
                values = array("f")
                for coordinate in coordinates:
                    if not isinstance(coordinate, (list, tuple)) or len(coordinate) != 2:
                        raise ValueError(f"UV attribute {name} must contain coordinate pairs")
                    pair = tuple(float(value) for value in coordinate)
                    if not all(math.isfinite(value) and abs(value) <= 1e5 for value in pair):
                        raise ValueError(f"UV attribute {name} contains an invalid coordinate")
                    values.extend(pair)
                if values.itemsize != 4:
                    raise ValueError("Platform array size is unsupported for UV attributes")
                if sys.byteorder != "little":
                    values.byteswap()
                packed_uv_attributes[name] = base64.b64encode(values.tobytes()).decode("ascii")
            if packed_uv_attributes:
                shape["uvAttributesPacked"] = packed_uv_attributes
        compact_shapes.append(shape)
    compact_scene["shapes"] = compact_shapes
    payload = json.dumps(compact_scene, ensure_ascii=True, separators=(",", ":"))
    payload = payload.replace("</", "<\\/").replace("\u2028", "\\u2028").replace("\u2029", "\\u2029")
    controls_button = (('<button id="graph-toggle" class="embedded-controls" type="button" '
                        'aria-expanded="true">Hide graph</button>'
                        '<button id="controls-toggle" class="embedded-controls" type="button" '
                        'aria-expanded="false">Preview controls</button>') if embedded else '')
    return (_PAGE.replace("__SCENE__", payload)
            .replace("__BODY_CLASS__", "embedded" if embedded else "")
            .replace("__EMBEDDED_CONTROL__", controls_button))


def open_preview(scene: dict) -> Path:
    """Write a local, non-repository preview page and open it in the browser."""
    destination = Path(tempfile.gettempdir()) / f"nsmbu-worldstudio-{uuid.uuid4().hex}.html"
    destination.write_text(build_document(scene), encoding="utf-8")
    if not webbrowser.open_new_tab(destination.as_uri()):
        raise OSError(f"Could not open browser for {destination}")
    return destination
